INSERT INTO songs VALUES('eb407749-c749-475f-a2fb-408522480671','f9889bf5-8a23-4fae-b698-99581823ca78',1,'Cenizas y Fuego','simple','Superar un gran reto que le rompió la vida: tocó fondo, perdió lo que era y ahora tiene que reinventarse desde cero. Empieza contenida y rota en los versos y explota en un estribillo de rabia y esperanza, un himno de volver a levantarse. Rock alternativo con guitarras distorsionadas y batería grande.','alternative rock, powerful female vocals, distorted guitars, heavy drums, explosive chorus, 128 bpm',unistr('[Intro]\u000a\u000a[Verse 1]\u000aLas paredes se cerraron hasta no dejar aire,\u000aEl peso del fracaso en cada respiración.\u000aLo que construí se deshizo entre mis manos,\u000aQuedó el silencio donde antes hubo un plan.\u000aCaminé por la línea de lo que ya murió,\u000aUn mapa borrado, un fondo sin salida.\u000a\u000a[Pre-Chorus]\u000aEl frío me marcó y las sombras me hundieron,\u000aPero en el barro todavía late una herida.\u000a\u000a[Chorus]\u000a¡Que se queme todo lo que ayer destruyó!\u000aDel polvo renace la fuerza que explotó.\u000aNo soy lo que perdí, no soy la caída,\u000aSoy la rabia y la esperanza que hoy se levanta.\u000a\u000a[Verse 2]\u000aRecojo los pedazos con las uñas rotas,\u000aSin redes de seguridad, sin nada atrás.\u000aReinventarme es el precio por sobrevivir,\u000aEscribir una historia nueva sobre esta cicatriz.\u000a\u000a[Bridge]\u000aQue tiemble la tierra cuando vuelva a pisar,\u000aNo busco perdón ni que nadie me mire.\u000aSolo quiero verme de pie otra vez,\u000aCon el fuego en los ojos y la voluntad en la piel.\u000a\u000a[Chorus]\u000a¡Que se queme todo lo que ayer destruyó!\u000aDel polvo renace la fuerza que explotó.\u000aNo soy lo que perdí, no ser la caída,\u000aSoy la rabia y la esperanza que hoy se levanta.\u000a\u000a[Outro]\u000aDesde cero. Desde las cenizas.\u000aLevántate otra vez. Levántate ahora.'),0,222.0,'es',NULL,NULL,'done','',NULL,'eb407749-c749-475f-a2fb-408522480671.voice.mp3',20