:20.51,"end":21.93}]},{"text":"El peso del fracaso en cada respiración.","start":24.44,"end":28.86,"matched":1,"words":[{"text":"El","start":24.44,"end":24.56},{"text":"peso","start":24.56,"end":25.02},{"text":"del","start":25.02,"end":25.34},{"text":"fracaso","start":25.34,"end":26.2},{"text":"en","start":26.2,"end":26.6},{"text":"cada","start":26.6,"end":27.18},{"text":"respiración.","start":27.18,"end":28.86}]},{"text":"Lo que construí se deshizo entre mis manos,","start":44.14,"end":49.06,"matched":1,"words":[{"text":"Lo","start":44.14,"end":44.32},{"text":"que","start":44.32,"end":44.82},{"text":"construí","start":44.82,"end":45.36},{"text":"se","start":45.36,"end":45.82},{"text":"deshizo","start":45.82,"end":46.52},{"text":"entre","start":46.52,"end":47.48},{"text":"mis","start":47.48,"end":48.16},{"text":"manos,","start":48.16,"end":49.06}]},{"text":"Quedó el silencio donde antes hubo un plan.","start":49.48,"end":53.62,"matched":1,"words":[{"text":"Quedó","start":49.48,"end":49.72},{"text":"el","start":49.72,"end":49.84},{"text":"silencio","start":49.84,"end":50.5},{"text":"donde","start":50.5,"end":51.18},{"text":"antes","start":51.18,"end":52.38},{"text":"hubo","start":52.38,"end":52.98},{"text":"un","start":52.98,"end":53.2},{"text":"plan.","start":53.2,"end":53.62}]},{"text":"Caminé por la línea de lo que ya murió,","start":53.62,"end":58.76,"matched":1,"words":[{"text":"Caminé","start":53.62,"end":54.82},{"text":"por","start":54.82,"end":55.4},{"text":"la","start":55.4,"end":55.74},{"text":"línea","start":55.74,"end":56.34},{"text":"de","start":56.34,"end":56.84},{"text":"lo","start":56.84,"end":57.18},{"text":"que","start":57.18,"end":57.44},{"text":"ya","start":57.44,"end":57.88},{"text":"murió,","start":57.88,"end":58.76}]},{"text":"Un mapa borrado, un fondo sin salida.","start":58.76,"end":63.6,"matched":0.71,"words":[{"text":"Un","start":58.76,"end":59.52},{"text":"mapa","start":59.52,"end":60.28},{"text":"borrado,","start":60.28,"end":61.04},{"text":"un","start":61.04,"end":61.28},{"text":"fondo","start":61.28,"end":61.76},{"text":"sin","start":61.76,"end":62.38},{"text":"salida.","start":62.38,"end":63.6}]},{"text":"El frío me marcó y las sombras me hundieron,","start":63.6,"end":68.31,"matched":0.78,"words":[{"text":"El","start":63.6,"end":64.06},{"text":"frío","start":64.06,"end":64.42},{"text":"me","start":64.42,"end":64.922},{"text":"marcó","start":64.922,"end":65.424},{"text":"y","start":65.424,"end":65.926},{"text":"las","start":65.926,"end":66.428},{"text":"sombras","start":66.428,"end":66.93},{"text":"me","start":66.93,"end":67.19},{"text":"hundieron,","start":67.19,"end":68.31}]},{"text":"Pero en el barro todavía late una herida.","start":68.31,"end":73.589,"matched":0.5,"words":[{"text":"Pero","start":68.31,"end":68.69},{"text":"en","start":68.69,"end":68.95},{"text":"el","start":68.95,"end":69.41},{"text":"barro","start":69.41,"end":70.246},{"text":"todavía","start":70.246,"end":71.081},{"text":"late","start":71.081,"end":71.917},{"text":"una","start":71.917,"end":72.753},{"text":"herida.","start":72.753,"end":73.589}]},{"text":"¡Que se queme todo lo que ayer destruyó!","start":73.589,"end":80.275,"matched":0.5,"words":[{"text":"¡Que","start":73.589,"end":74.424},{"text":"se","start":74.424,"end":75.26},{"text":"queme","start":75.26,"end":76.096},{"text":"todo","start":76.096,"end":76.932},{"text":"lo","start":76.932,"end":77.767},{"text":"que","start":77.767,"end":78.603},{"text":"ayer","start":78.603,"end":79.439},{"text":"destruyó!","start":79.439,"end":80.275}]},{"text":"Del polvo renace la fuerza que explotó.","start":80.275,"end":86.125,"matched":0.71,"words":[{"text":"Del","start":80.275,"end":81.111},{"text":"polvo","start":81.111,"end":81.946},{"text":"renace","start":81.946,"end":82.782},{"text":"la","start":82.782,"end":83.618},{"text":"fuerza","start":83.618,"end":84.454},{"text":"que","start":84.454,"end":85.289},{"text":"explotó.","start":85.289,"end":86.125}]},{"text":"No soy lo que perdí, no soy la caída,","start":86.125,"end":93.647,"matched":1,"words":[{"text":"No","start":86.125,"end":86.961},{"text":"soy","start":86.961,"end":87.797},{"text":"lo","start":87.797,"end":88.632},{"text":"que","start":88.632,"end":89.468},{"text":"perdí,","start":89.468,"end":90.304},{"text":"no","start":90.304,"end":91.139},{"text":"soy","start":91.139,"end":91.975},{"text":"la","start":91.975,"end":92.811},{"text":"caída,","start":92.811,"end":93.647}]},{"text":"Soy la rabia y la esperanza que hoy se levanta.","start":93.647,"end":102.004,"matched":0.8,"words":[{"text":"Soy","start":93.647,"end":94.483},{"text":"la","start":94.483,"end":95.318},{"text":"rabia","start":95.318,"end":96.154},{"text":"y","start":96.154,"end":96.99},{"text":"la","start":96.99,"end":97.826},{"text":"esperanza","start":97.826,"end":98.661},{"text":"que","start":98.661,"end":99.497},{"text":"hoy","start":99.497,"end":100.333},{"text":"se","start":100.333,"end":101.169},{"text":"levanta.","start":101.169,"end":102.004}]},{"text":"Recojo los pedazos con las uñas rotas,","start":102.004,"end":106.66,"matched":0.57,"words":[{"text":"Recojo","start":102.004,"end":102.84},{"text":"los","start":102.84,"end":103.32},{"text":"pedazos","start":103.32,"end":104.64},{"text":"con","start":104.64,"end":105.145},{"text":"las","start":105.145,"end":105.65},{"text":"uñas","start":105.65,"end":106.155},{"text":"rotas,","start":106.155,"end":106.66}]},{"text":"Sin redes de seguridad, sin nada atrás.","start":106.66,"end":113.9,"matched":1,"words":[{"text":"Sin","start":106.66,"end":107.14},{"text":"redes","start":107.14,"end":107.64},{"text":"de","start":107.64,"end":108.1},{"text":"seguridad,","start":108.1,"end":109.04},{"text":"sin","start":111.82,"end":112.56},{"text":"nada","start":112.56,"end":113.14},{"text":"atrás.","start":113.14,"end":113.9}]},{"text":"Reinventarme es el precio por sobrevivir,","start":113.9,"end":118.62,"matched":1,"words":[{"text":"Reinventarme","start":113.9,"end":114.98},{"text":"es","start":114.98,"end":115.38},{"text":"el","start":115.38,"end":115.62},{"text":"precio","start":115.62,"end":116.38},{"text":"por","start":116.38,"end":117.12},{"text":"sobrevivir,","start":117.12,"end":118.62}]},{"text":"Escribir una historia nueva sobre esta cicatriz.","start":118.62,"end":124.72,"matched":0.71,"words":[{"text":"Escribir","start":118.62,"end":119.54},{"text":"una","start":119.54,"end":119.94},{"text":"historia","start":119.94,"end":120.84},{"text":"nueva","start":120.84,"end":121.74},{"text":"sobre","start":121.74,"end":122.4},{"text":"esta","start":122.4,"end":123.18},{"text":"cicatriz.","start":123.18,"end":124.72}]},{"text":"Que tiemble la tierra cuando vuelva a pisar,","start":124.72,"end":132.92,"matched":0.75,"words":[{"text":"Que","start":124.72,"end":125.745},{"text":"tiemble","start":125.745,"end":126.77},{"text":"la","start":126.77,"end":127.795},{"text":"tierra","start":127.795,"end":128.82},{"text":"cuando","start":128.82,"end":129.845},{"text":"vuelva","start":129.845,"end":130.87},{"text":"a","start":130.87,"end":131.895},{"text":"pisar,","start":131.895,"end":132.92}]},{"text":"No busco perdón ni que nadie me mire.","start":136.59,"end":141.97,"matched":0.88,"words":[{"text":"No","start":136.59,"end":137.11},{"text":"busco","start":137.11,"end":137.97},{"text":"perdón","start":137.97,"end":138.87},{"text":"ni","start":138.87,"end":139.21},{"text":"que","start":139.21,"end":139.61},{"text":"nadie","start":139.61,"end":140.27},{"text":"me","start":140.27,"end":141.12},{"text":"mire.","start":141.12,"end":141.97}]},{"text":"Solo quiero verme de pie otra vez,","start":141.97,"end":147.06,"matched":0.71,"words":[{"text":"Solo","start":141.97,"end":142.47},{"text":"quiero","start":142.47,"end":143.07},{"text":"verme","start":143.07,"end":143.77},{"text":"de","start":143.77,"end":144.35},{"text":"pie","start":144.35,"end":145.05},{"text":"otra","start":145.05,"end":146.055},{"text":"vez,","start":146.055,"end":147.06}]},{"text":"Con el fuego en los ojos y la voluntad en la piel.","start":147.06,"end":156.294,"matched":0.75,"words":[{"text":"Con","start":147.06,"end":147.7},{"text":"el","start":147.7,"end":148},{"text":"fuego","start":148,"end":148.532},{"text":"en","start":148.532,"end":149.064},{"text":"los","start":149.064,"end":149.596},{"text":"ojos","start":149.596,"end":150.128},{"text":"y","start":150.128,"end":150.66},{"text":"la","start":150.66,"end":151.04},{"text":"voluntad","start":151.04,"end":152.16},{"text":"en","start":152.16,"end":153.538},{"text":"la","start":153.538,"end":154.916},{"text":"piel.","start":154.916,"end":156.294}]},{"text":"¡Que se queme todo lo que ayer destruyó!","start":156.294,"end":164.494,"matched":0.5,"words":[{"text":"¡Que","start":156.294,"end":157.319},{"text":"se","start":157.319,"end":158.344},{"text":"queme","start":158.344,"end":159.369},{"text":"todo","start":159.369,"end":160.394},{"text":"lo","start":160.394,"end":161.419},{"text":"que","start":161.419,"end":162.444},{"text":"ayer","start":162.444,"end":163.469},{"text":"destruyó!","start":163.469,"end":164.494}]},{"text":"Del polvo renace la fuerza que explotó.","start":167.318,"end":174.618,"matched":0.71,"words":[{"text":"Del","start":167.318,"end":168.361},{"text":"polvo","start":168.361,"end":169.404},{"text":"renace","start":169.404,"end":170.447},{"text":"la","start":170.447,"end":171.489},{"text":"fuerza","start":171.489,"end":172.532},{"text":"que","start":172.532,"end":173.575},{"text":"explotó.","start":173.575,"end":174.618}]},{"text":"No soy lo que perdí, no ser la caída,","start":175.47,"end":179.51,"matched":1,"words":[{"text":"No","start":175.47,"end":175.59},{"text":"soy","start":175.59,"end":175.81},{"text":"lo","start":175.81,"end":176.07},{"text":"que","start":176.07,"end":176.33},{"text":"perdí,","start":176.33,"end":177.45},{"text":"no","start":177.45,"end":178.03},{"text":"ser","start":178.03,"end":178.39},{"text":"la","start":178.39,"end":178.77},{"text":"caída,","start":178.77,"end":179.51}]},{"text":"Soy la rabia y la esperanza que hoy se levanta.","start":179.71,"end":184.099,"matched":0.8,"words":[{"text":"Soy","start":179.71,"end":180.03},{"text":"la","start":180.03,"end":180.49},{"text":"rabia","start":180.49,"end":180.79},{"text":"y","start":180.79,"end":180.97},{"text":"la","start":180.97,"end":181.41},{"text":"esperanza","start":181.41,"end":182.17},{"text":"que","start":182.17,"end":182.652},{"text":"hoy","start":182.652,"end":183.134},{"text":"se","start":183.134,"end":183.616},{"text":"levanta.","start":183.616,"end":184.099}]},{"text":"Desde cero. Desde las cenizas.","start":184.099,"end":186.509,"matched":0.2,"words":[{"text":"Desde","start":184.099,"end":184.581},{"text":"cero.","start":184.581,"end":185.063},{"text":"Desde","start":185.063,"end":185.545},{"text":"las","start":185.545,"end":186.027},{"text":"cenizas.","start":186.027,"end":186.509}]},{"text":"Levántate otra vez. Levántate ahora.","start":186.509,"end":188.92,"matched":0,"words":[{"text":"Levántate","start":186.509,"end":186.991},{"text":"otra","start":186.991,"end":187.474},{"text":"vez.","start":187.474,"end":187.956},{"text":"Levántate","start":187.956,"end":188.438},{"text":"ahora.","start":188.438,"end":188.92}]}]}','{"keepHighsHz":3000}','104fc433-13a5-46cc-8d01-58bea0298ad3',0.8761999999999999789);
INSERT INTO songs VALUES('4c3dcc96-26de-49b3-a0fd-5b1435c38892','f4188d12-7811-4454-8522-ffc35553e74c',0,'El milagro de la vida','simple','El milagro de la vida: una balada de asombro y gratitud ante una vida nueva que llega y lo cambia todo. Versos íntimos, casi susurrados, sobre el miedo y la espera; un estribillo amplio y luminoso que celebra el primer latido, la primera mirada, la promesa de cuidarla siempre. Balada pop con piano, cuerdas y un crescendo emotivo al final.','pop ballad, emotional crescendo, piano and strings, expressive female vocals, slow tempo',unistr('[Intro]\u000a\u000a[Verse 1]\u000aEn la penumbra de la espera,\u000aen el silencio que todo lo define.\u000aThemede en tus movimientos minúsculos,\u000amiedo y anhelo se vuelven uno aquí.\u000aEl calendario pesa cada día marcado,\u000auna promesa escrita antes incluso nacer.\u000a\u000a[Pre-Chorus]\u000aY entonces ocurre, el tiempo se detiene,\u000aun soplo de luz que la espera sostiene.\u000a\u000a[Chorus]\u000aEs tu primer latido, un universo entero,\u000apromesa grabada en cada línea y piel entera.\u000aTu primera mirada que lo cambia todo hoy,\u000acuidarte siempre, es el voto que doy.\u000aLuminoso milagro que brota del alma,\u000ael inicio dulce de nuestra vida en calma.\u000a\u000a[Verse 2]\u000aPasos pequeños grabados ya en la mente,\u000atu sueño despierta y nos define a los dos.\u000aEl futuro se abre con tu suave llegada,\u000acada respiro tuyo es una nueva jornada.\u000a\u000a[Bridge]\u000aA través de las sombras que antes temíamos,\u000amira cómo crece esta vida anhelada.\u000aUn milagro que broda del alma profunda,\u000aun camino largo donde tu amor nos inunda.\u000a\u000a[Chorus]\u000aEs tu primer latido, el universo entero,\u000apromesa grabada en cada línea y piel entera.\u000aTu primera mirada que lo cambia ser hoy,\u000acuidarte siempre es el voto que doy.\u000aLuminoso milagro que brota del alma,\u000ael inicio dulce de nuestra vida en calma.\u000a\u000a[Outro]\u000aEl primer latido...'),0,172.0,'es',NULL,NULL,'done','',NULL,'4c3dcc96-26de-49b3-a0fd-5b1435c38892.mp3',NULL,'E♭ major','4',NULL,1788829591544,1788829889119,NULL,NULL,NULL,'4c3dcc96-26de-49b3-a0fd-5b1435c38892.raw.mp3','off',0,'dd1566a4-be12-4fe6-b515-bb92efd35a6e',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,NULL,NULL);
INSERT INTO songs VALUES('67be59a4-634b-4313-9794-86dda811487f','f4188d12-7811-4454-8522-ffc35553e74c',1,'El milagro de la vida','simple','El milagro de la vida: una balada de asombro y gratitud ante una vida nueva que llega y lo cambia todo. Versos íntimos, casi susurrados, sobre el miedo y la espera; un estribillo amplio y luminoso que celebra el primer latido, la primera mirada, la promesa de cuidarla siempre. Balada pop con piano, cuerdas y un crescendo emotivo al final.','pop ballad, emotional crescendo, piano and strings, expressive female vocals, slow tempo',unistr('[Intro]\u000a\u000a[Verse 1]\u000aEn la penumbra de la espera,\u000aen el silencio que todo lo define.\u000aThemede en tus movimientos minúsculos,\u000amiedo y anhelo se vuelven uno aquí.\u000aEl calendario pesa cada día marcado,\u000auna promesa escrita antes incluso nacer.\u000a\u000a[Pre-Chorus]\u000aY entonces ocurre, el tiempo se detiene,\u000aun soplo de luz que la espera sostiene.\u000a\u000a[Chorus]\u000aEs tu primer latido, un universo entero,\u000apromesa grabada en cada línea y piel entera.\u000aTu primera mirada que lo cambia todo hoy,\u000acuidarte siempre, es el voto que doy.\u000aLuminoso milagro que brota del alma,\u000ael inicio dulce de nuestra vida en calma.\u000a\u000a[Verse 2]\u000aPasos pequeños grabados ya en la mente,\u000atu sueño despierta y nos define a los dos.\u000aEl futuro se abre con tu suave llegada,\u000acada respiro tuyo es una nueva jornada.\u000a\u000a[Bridge]\u000aA través de las sombras que antes temíamos,\u000amira cómo crece esta vida anhelada.\u000aUn milagro que broda del alma profunda,\u000aun camino largo donde tu amor nos inunda.\u000a\u000a[Chorus]\u000aEs tu primer latido, el universo entero,\u000apromesa grabada en cada línea y piel entera.\u000aTu primera mirada que lo cambia ser hoy,\u000acuidarte siempre es el voto que doy.\u000aLuminoso milagro que brota del alma,\u000ael inicio dulce de nuestra vida en calma.\u000a\u000a[Outro]\u000aEl primer latido...'),0,172.0,'es',NULL,NULL,'done','',NULL,'67be59a4-634b-4313-9794-86dda811487f.mp3',NULL,'E♭ major','4',NULL,1788829591544,1788829890360,NULL,NULL,NULL,'67be59a4-634b-4313-9794-86dda811487f.raw.mp3','off',0,'dd1566a4-be12-4fe6-b515-bb92efd35a6e',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,NULL,NULL);
