INSERT INTO songs VALUES('aa7465fc-1ad9-4d7b-ba77-bd9060917afe','9b999237-3933-4583-b74e-82a67b0bff47',0,'Sin Aire','custom','','alternative rock, nu metal, powerful female vocals, raspy screamed chorus, half-rapped rhythmic verses, distorted electric guitars, heavy drums, dark electronic synth textures, glitchy sampled beats, quiet verse loud chorus, emotional, cathartic, 105 bpm',unistr('[Intro]\u000aNo sé qué me pasa\u000aNo sé qué me pasa\u000a\u000a[Verse 1]\u000aMe despierto y el techo pesa más que ayer,\u000aCuento hasta diez y el aire no me quiere entrar.\u000aTodos me preguntan y no sé qué responder,\u000aSonrío por inercia, por no tener que hablar.\u000aHay un ruido en mi cabeza que no sabe callar,\u000aUn eco que repite que algo está mal.\u000aBusco la grieta y no la puedo encontrar,\u000aCorro en círculos dentro de mi propia piel.\u000a\u000a[Pre-Chorus]\u000aTodo va demasiado rápido,\u000aTodo va demasiado lento.\u000aMe ahogo en un cuarto lleno de gente,\u000aY nadie ve que me estoy hundiendo.\u000a\u000a[Chorus]\u000a¡No sé qué está mal conmigo!\u000aGrito y no me escucho, no me reconozco.\u000a¡Sofocada en mi propio ruido!\u000aDime qué me pasa, dime qué me rompo.\u000aNo sé qué está mal conmigo,\u000aPero sigo aquí, respirando a pedazos.\u000a\u000a[Verse 2]\u000aMiro mis manos y no parecen las mías,\u000aUn extraño vive dentro de mi voz.\u000aDicen que es una fase, que son solo días,\u000aPero cada día pesa más que el anterior.\u000aNo pido respuestas, pido un poco de aire,\u000aUn segundo donde el pecho no me apriete.\u000aSi algo se rompió, que alguien me lo señale,\u000aPorque no sé dónde duele, solo sé que duele.\u000a\u000a[Pre-Chorus]\u000aTodo va demasiado rápido,\u000aTodo va demasiado lento.\u000aMe ahogo en un cuarto lleno de gente,\u000aY nadie ve que me estoy hundiendo.\u000a\u000a[Chorus]\u000a¡No sé qué está mal conmigo!\u000aGrito y no me escucho, no me reconozco.\u000a¡Sofocada en mi propio ruido!\u000aDime qué me pasa, dime qué me rompo.\u000aNo sé qué está mal conmigo,\u000aPero sigo aquí, respirando a pedazos.\u000a\u000a[Bridge]\u000aY de repente... silencio.\u000aNo tengo que entenderlo todo hoy.\u000aNo tengo que arreglarme entera hoy.\u000aPuedo estar rota y seguir siendo yo.\u000aRespira. Respira. Respira.\u000a\u000a[Final Chorus]\u000a¡No sé qué está mal conmigo!\u000aY tal vez no importa tener la respuesta.\u000a¡Ya no me ahogo en mi propio ruido!\u000aEl aire vuelve, el aire vuelve despacio.\u000aNo sé qué está mal conmigo,\u000aPero sé que va a estar bien, va a estar bien.\u000a\u000a[Outro]\u000aVa a estar bien.\u000aAunque hoy no lo entienda,\u000aVa a estar bien.'),0,210.0,'es',NULL,NULL,'done','',NULL,'aa7465fc-1ad9-4d7b-ba77-bd9060917afe.mp3',200,'E minor','4',NULL,1788887022751,1789003975039,NULL,NULL,NULL,'aa7465fc-1ad9-4d7b-ba77-bd9060917afe.raw.mp3','off',0,'25e4a789-ff12-40b4-8352-a253a04dc300',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'104fc433-13a5-46cc-8d01-58bea0298ad3',0.8185000000000000053);
