INSERT INTO songs VALUES('960219fb-e797-48a3-8e22-d9fe64d40b21','79f77f9f-c607-4776-8d56-eb3aa3df7353',1,'Las Llaves','custom','','afro latino, reggaeton, dembow beat, latin percussion, congas and bongos, deep bass, warm male vocals, smooth melodic flow, emotional and intimate verses, building tension bridge, explosive drop chorus, tropical, 96 bpm',unistr('[Intro]\u000aCojo las llaves, mor.\u000aNo digas nada, solo súbete.\u000a\u000a[Verse 1]\u000aLunes de oficina, la ciudad me tiene cansado,\u000aEl celular timbrando y yo mirando pa'' otro lado.\u000aCojo las llaves, te miro y no hay que hablar,\u000aTú ya sabes que hoy nos vamos a escapar.\u000aBajamos por la autopista con la ventana abierta,\u000aEl aire del monte entrando, la vida menos tiesa.\u000aGuatapé, Jardín o Santa Fe, me da igual,\u000aCualquier pueblito contigo es un lugar especial.\u000a\u000a[Pre-Chorus]\u000aNo necesito lujo, ni un hotel de cinco estrellas,\u000aSolo un parque, una banca, un tinto y tu mano en la mía.\u000a\u000a[Chorus]\u000aCojo las llaves y me escapo contigo,\u000aA puebliar cerquita, a olvidarme del ruido.\u000aLas cosas pequeñas son las que me llenan,\u000aUn atardecer, tu risa y una arepa en la esquina.\u000aCojo las llaves y me voy contigo,\u000aQue la vida es esto, mor, lo demás es ruido.\u000a\u000a[Verse 2]\u000aUn fresco en la plaza mirando la gente pasar,\u000aLa iglesia, las casas de colores, el balcón de par en par.\u000aTú tomando fotos de flores que no sabes el nombre,\u000aY yo tomándote fotos a ti, mor, pa'' que no se me borre.\u000aLa señora del restaurante que nos trató como hijos,\u000aEl río frío en los pies, los dos muertos de risa.\u000aNo hay nada que comprar, no hay nada que probar,\u000aSolo estar aquí contigo y dejar el tiempo pasar.\u000a\u000a[Pre-Chorus]\u000aNo necesito lujo, ni un hotel de cinco estrellas,\u000aSolo un parque, una banca, un tinto y tu mano en la mía.\u000a\u000a[Chorus]\u000aCojo las llaves y me escapo contigo,\u000aA puebliar cerquita, a olvidarme del ruido.\u000aLas cosas pequeñas son las que me llenan,\u000aUn atardecer, tu risa y una arepa en la esquina.\u000aCojo las llaves y me voy contigo,\u000aQue la vida es esto, mor, lo demás es ruido.\u000a\u000a[Bridge]\u000aY si el mundo corre, que corra sin nosotros.\u000aY si el tiempo aprieta, que apriete a los otros.\u000aAquí no hay afán, aquí no hay reloj,\u000aSolo tú, solo yo, solo el sol.\u000aSolo tú... solo yo...\u000a\u000a[Drop]\u000a¡Cojo las llaves!\u000a¡Y me escapo contigo!\u000a¡Cojo las llaves!\u000a¡Que lo demás es ruido!\u000a\u000a[Chorus]\u000aCojo las llaves y me escapo contigo,\u000aA puebliar cerquita, a olvidarme del ruido.\u000aLas cosas pequeñas son las que me llenan,\u000aUn atardecer, tu risa y una arepa en la esquina.\u000a\u000a[Outro]\u000aCojo las llaves, mor.\u000aSúbete, que nos vamos.\u000aLo demás es ruido.'),0,210.0,'es',NULL,NULL,'done','',NULL,'960219fb-e797-48a3-8e22-d9fe64d40b21.mp3',90,'A minor','4',NULL,1788889297909,1788894677543,NULL,NULL,NULL,'960219fb-e797-48a3-8e22-d9fe64d40b21.raw.mp3','clear',1,'a9137dae-4b01-433f-9f1a-7796c6d4bb60','2e06a298-bbf2-4562-a311-d92994832575',NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,NULL,NULL);
INSERT INTO songs VALUES('82208a5d-e8a7-438e-9d80-b8e387300f61','9c9728af-e3a7-4b6e-aca3-3b52000a6b71',0,'Como Si Te Hubieras Ido','custom','','A modern Mexican banda ballad, regional Mexican with tuba, brass section and clarinets over polished contemporary production. An old male vocalist in his sixties, in the style of Vicente Fernández, delivers the heartbroken lyrics with a deep, gravelly, weathered baritone male voice, classic ranchera vibrato and a dramatic mariachi grito. Grieving and angry. 95 bpm.',unistr('[Intro]\u000a¡Ay, mujer!\u000aCómo me dejaste...\u000a\u000a[Verse 1]\u000aTe fuiste sin decirme una palabra,\u000aSin darme tiempo de pedirte perdón.\u000aDejaste tu vestido en la ventana\u000aY el café servido en tu rincón.\u000aLa gente me pregunta qué ha pasado,\u000aYo digo que se acabó nuestro amor.\u000aQue me dejaste solo y arruinado,\u000aQue te fuiste con otro, que no sé quién es mejor.\u000a\u000a[Chorus]\u000a¡Y me duele, me duele como el diablo!\u000aTengo rabia de verte en cada esquina.\u000aBrindo por ti con este trago amargo,\u000aMaldigo el día que te fuiste de mi vida.\u000a¡Ay, cómo te odio por dejarme!\u000aY cómo te amo, aunque me mate.\u000a\u000a[Verse 2]\u000aCompré las flores que a ti te gustaban,\u000aLas mismas que llevaba a nuestra casa.\u000aPero hoy no van a la mesa de la sala,\u000aHoy las llevo a una tierra que te abraza.\u000aNo fue con otro, no fue por la puerta,\u000aNo fue un adiós, fue Dios que te llevó.\u000aY yo aquí gritando a la tumba abierta,\u000a¿Por qué te fuiste tú y no me fui yo?\u000a\u000a[Chorus]\u000a¡Y me duele, me duele como el diablo!\u000aTengo rabia de verte en cada esquina.\u000aBrindo por ti con este trago amargo,\u000aMaldigo el día que te fuiste de mi vida.\u000a¡Ay, cómo te odio por dejarme!\u000aY cómo te amo, aunque me mate.\u000a\u000a[Bridge]\u000aQue toquen las trompetas, que lloren los violines,\u000aQue el mundo entero sepa que me quedé sin ti.\u000aTengo rabia con el cielo, tengo rabia conmigo,\u000aPor cada te quiero que no te dije a ti.\u000a¡Ay, ay, ay!\u000a\u000a[Chorus]\u000a¡Y me duele, me duele como el diablo!\u000aYa no hay rabia, solo queda esta herida.\u000aBrindo por ti con el último trago,\u000aBendigo el día que llegaste a mi vida.\u000a¡Ay, cómo te extraño, vida mía!\u000aY cómo te amo, hasta que me muera.\u000a\u000a[Outro]\u000aDescansa, mi amor.\u000aAquí te espero, aunque me tarde.\u000a¡Ay, mujer!'),0,210.0,'es',NULL,NULL,'done','',NULL,'82208a5d-e8a7-438e-9d80-b8e387300f61.mp3',36,'F major','3',NULL,1788890876338,1788891414370,NULL,NULL,NULL,'82208a5d-e8a7-438e-9d80-b8e387300f61.raw.mp3','warm',1,NULL,NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,NULL,NULL);
INSERT INTO songs VALUES('b8bc87f8-a0dd-4a2f-95ec-304ea8945a20','11c68e5e-b93a-4dda-bfe0-329763c4e72f',0,'Te Fuiste Sin Avisar','custom','','modern mariachi, mariachi pop ballad, ranchera romántica, warm male baritone-tenor vocals with emotional vibrato, heartfelt gritos, soaring trumpets, lush violins, vihuela, guitarrón, requinto, slow 6/8 feel, cinematic build, polished contemporary production, melancholic, Spanish',unistr('[Intro]\u000a(trompetas)\u000a\u000a[Verse 1]\u000aDicen en el pueblo que te fuiste,\u000aque ni la puerta cerraste al salir.\u000aDejaste tu vestido en la silla,\u000atu café a la mitad, sin despedir.\u000aY yo que te di todo, mujer,\u000ame dejaste hablando con la pared.\u000a\u000a[Pre-Chorus]\u000aTodos me preguntan si hay otro,\u000asi te cansaste de este pobre loco.\u000a\u000a[Chorus]\u000aTe fuiste sin avisar,\u000asin una carta, sin un adiós,\u000ay aquí me tienes tomando\u000acon el mariachi y con tu voz.\u000aTe fuiste sin avisar,\u000ay no sé a quién reclamar,\u000asi te llevaron los celos, el orgullo,\u000ao algo que yo no supe dar.\u000a\u000a[Verse 2]\u000aTu lado de la cama sigue frío,\u000atu perfume no se quiere despedir.\u000aMi madre dice que te olvide,\u000aque hay muchas que quisieran estar aquí.\u000aPero es que no entiendo, mi amor,\u000acómo te fuiste sin decirme por qué.\u000a\u000a[Chorus]\u000aTe fuiste sin avisar,\u000asin una carta, sin un adiós,\u000ay aquí me tienes tomando\u000acon el mariachi y con tu voz.\u000aTe fuiste sin avisar,\u000ay no sé a quién reclamar,\u000asi te llevaron los celos, el orgullo,\u000ao algo que yo no supe dar.\u000a\u000a[Bridge]\u000aPerdóname si hablé de traición,\u000asi dejé que el pueblo pensara en otro amor.\u000aNadie sabe que vengo al panteón\u000aa dejarte flores blancas y mi voz.\u000aNo te fuiste con nadie, lo sé,\u000ate fuiste una madrugada sin amanecer,\u000ay prefiero pensar que huiste de mí,\u000aporque duele menos que saber que ya no estás aquí.\u000a\u000a[Final Chorus]\u000aTe fuiste sin avisar,\u000asin una carta, sin un adiós,\u000ay aquí me tienes cantando\u000asobre tu nombre, sobre esta cruz.\u000aTe fuiste sin avisar,\u000aya no hay a quién reclamar,\u000ayo te guardo tu lado de la cama\u000apor si Dios te deja regresar.\u000a\u000a[Outro]\u000a(grito) ¡Y aquí te sigo esperando, mi reina!\u000aTe fuiste sin avisar...'),0,210.0,'es',NULL,NULL,'done','',NULL,'b8bc87f8-a0dd-4a2f-95ec-304ea8945a20.mp3',65,'E minor','4',NULL,1788891177437,1789070706222,NULL,NULL,NULL,'b8bc87f8-a0dd-4a2f-95ec-304ea8945a20.raw.mp3','clear',1,'8475b49e-f832-4d74-b7de-f07c90c7e751','044143e1-87c5-4d8c-9d29-e894c24637af',NULL,NULL,NULL,0,'done','25189bf2-228c-4099-844b-02e07b88968f','b8bc87f8-a0dd-4a2f-95ec-304ea8945a20.video.mp4','',NULL,'{"character":"A handsome 32-year-old Mexican man with a warm baritone face, short styled black hair, wearing an embroidered western jacket over a plaid shirt, expressive eyes full of longing.","scenes":[{"section":"Intro","prompt":"Medium shot at dusk in a dusty cobblestone plaza; the character sits on a weathered wooden bench alone under a flickering lamp, his face cast in orange and blue light, looking pensively into the distance.","duration":7.38},{"section":"Verse 1","prompt":"Close-up indoors in a dimly lit room; the character stands over an empty chair with a half-drunk cup of coffee nearby, golden moonlight streaming through a window across his sorrowful expression.","duration":25.85},{"section":"Pre-Chorus","prompt":"Medium shot at a small rustic tavern table; he holds his head in one hand and looks toward unseen townsfolk off camera with a conflicted, wounded look under warm yellow light.","duration":7.38},{"section":"Chorus","prompt":"Close-up medium lighting — warm orange lamplight from below heightening the emotion as he pours his soul out toward the horizon, singing the high notes with a distressed face.","duration":18.46},{"section":"Chorus","prompt":"Close-up medium lighting — warm orange lamplight from below heightening the emotion as he pours his soul out toward the horizon, singing the high notes with a distressed face., different camera angle, closer shot","duration":14.77},{"section":"Verse 2","prompt":"Medium shot in his bedroom at night with deep blue and magenta ambient light; the character sits on the edge of a large bed, staring into an empty space next to him with heavy eyes and slumped shoulders.","duration":25.85},{"section":"Chorus","prompt":"Close-up medium lighting — warm orange lamplight from below heightening the emotion as he pours his soul out toward the horizon, singing the high notes with a distressed face.","duration":18.46},{"section":"Chorus","prompt":"Close-up medium lighting — warm orange lamplight from below heightening the emotion as he pours his soul out toward the horizon, singing the high notes with a distressed face., different camera angle, closer shot","duration":14.77},{"section":"Bridge","prompt":"Medium shot in a cemetery at dawn under misty white and lilac light; flowers lie on a grave stone nearby, the character stands bowed over them while looking upward towards the early morning sky.","duration":18.46},{"section":"Bridge","prompt":"Medium shot in a cemetery at dawn under misty white and lilac light; flowers lie on a grave stone nearby, the character stands bowed over them while looking upward towards the early morning sky., different camera angle, closer shot","duration":14.77},{"section":"Final Chorus","prompt":"Close-up extreme warm lighting — soft pink and golden sunrise glow illuminates his face as he sings with tears in his eyes at the cemetery scene beside the white flowers.","duration":18.46},{"section":"Final Chorus","prompt":"Close-up extreme warm lighting — soft pink and golden sunrise glow illuminates his face as he sings with tears in his eyes at the cemetery scene beside the white flowers., different camera angle, closer shot","duration":18.46},{"section":"Outro","prompt":"Wide medium shot a moment later; mist rising around him under pale grey morning light, his hand raised slightly to the side for a final heartfelt mariachi cry into an empty plaza","duration":6.929999999999962}],"total":210,"lyrics":[{"text":"(trompetas)","start":0,"end":2.5,"matched":0,"words":[{"text":"(trompetas)","start":0,"end":2.5}]},{"text":"Dicen en el pueblo que te fuiste,","start":29.67,"end":33.73,"matched":1,"words":[{"text":"Dicen","start":29.67,"end":30.51},{"text":"en","start":30.51,"end":30.77},{"text":"el","start":30.77,"end":31.05},{"text":"pueblo","start":31.05,"end":31.39},{"text":"que","start":31.39,"end":31.99},{"text":"te","start":31.99,"end":32.35},{"text":"fuiste,","start":32.35,"end":33.73}]},{"text":"que ni la puerta cerraste al salir.","start":34.49,"end":39.79,"matched":0.86,"words":[{"text":"que","start":34.49,"end":34.63},{"text":"ni","start":34.63,"end":34.87},{"text":"la","start":34.87,"end":35.11},{"text":"puerta","start":35.11,"end":36.49},{"text":"cerraste","start":36.49,"end":38.05},{"text":"al","start":38.05,"end":38.33},{"text":"salir.","start":38.33,"end":39.79}]},{"text":"Dejaste tu vestido en la silla,","start":42.06,"end":45.12,"matched":1,"words":[{"text":"Dejaste","start":42.06,"end":42.38},{"text":"tu","start":42.38,"end":43.1},{"text":"vestido","start":43.1,"end":44.16},{"text":"en","start":44.16,"end":44.36},{"text":"la","start":44.36,"end":44.7},{"text":"silla,","start":44.7,"end":45.12}]},{"text":"tu café a la mitad, sin despedir.","start":45.28,"end":47.2,"matched":1,"words":[{"text":"tu","start":45.28,"end":45.48},{"text":"café","start":45.48,"end":45.96},{"text":"a","start":45.96,"end":46.3},{"text":"la","start":46.3,"end":46.52},{"text":"mitad,","start":46.52,"end":46.96},{"text":"sin","start":46.96,"end":47.08},{"text":"despedir.","start":47.08,"end":47.2}]},{"text":"Y yo que te di todo, mujer,","start":47.2,"end":48.04,"matched":0.57,"words":[{"text":"Y","start":47.2,"end":47.32},{"text":"yo","start":47.32,"end":47.44},{"text":"que","start":47.44,"end":47.56},{"text":"te","start":47.56,"end":47.68},{"text":"di","start":47.68,"end":47.8},{"text":"todo,","start":47.8,"end":47.92},{"text":"mujer,","start":47.92,"end":48.04}]},{"text":"me dejaste hablando con la pared.","start":48.04,"end":48.76,"matched":0.67,"words":[{"text":"me","start":48.04,"end":48.16},{"text":"dejaste","start":48.16,"end":48.28},{"text":"hablando","start":48.28,"end":48.4},{"text":"con","start":48.4,"end":48.52},{"text":"la","start":48.52,"end":48.64},{"text":"pared.","start":48.64,"end":48.76}]},{"text":"Todos me preguntan si hay otro,","start":48.76,"end":49.48,"matched":0.5,"words":[{"text":"Todos","start":48.76,"end":48.88},{"text":"me","start":48.88,"end":49},{"text":"preguntan","start":49,"end":49.12},{"text":"si","start":49.12,"end":49.24},{"text":"hay","start":49.24,"end":49.36},{"text":"otro,","start":49.36,"end":49.48}]},{"text":"si te cansaste de este pobre loco.","start":49.48,"end":50.32,"matched":0.86,"words":[{"text":"si","start":49.48,"end":49.6},{"text":"te","start":49.6,"end":49.72},{"text":"cansaste","start":49.72,"end":49.84},{"text":"de","start":49.84,"end":49.96},{"text":"este","start":49.96,"end":50.08},{"text":"pobre","start":50.08,"end":50.2},{"text":"loco.","start":50.2,"end":50.32}]},{"text":"Te fuiste sin avisar,","start":51.84,"end":54.64,"matched":1,"words":[{"text":"Te","start":51.84,"end":52.12},{"text":"fuiste","start":52.12,"end":52.5},{"text":"sin","start":52.5,"end":53.18},{"text":"avisar,","start":53.18,"end":54.64}]},{"text":"sin una carta, sin un adiós,","start":54.64,"end":55.6,"matched":0.83,"words":[{"text":"sin","start":54.64,"end":54.8},{"text":"una","start":54.8,"end":54.96},{"text":"carta,","start":54.96,"end":55.12},{"text":"sin","start":55.12,"end":55.28},{"text":"un","start":55.28,"end":55.44},{"text":"adiós,","start":55.44,"end":55.6}]},{"text":"y aquí me tienes tomando","start":55.6,"end":57.6,"matched":1,"words":[{"text":"y","start":55.6,"end":55.78},{"text":"aquí","start":55.78,"e