INSERT INTO songs VALUES('cacb4f5b-580c-4b24-9611-0592891c934b','11c68e5e-b93a-4dda-bfe0-329763c4e72f',1,'Te Fuiste Sin Avisar','custom','','modern mariachi, mariachi pop ballad, ranchera romántica, warm male baritone-tenor vocals with emotional vibrato, heartfelt gritos, soaring trumpets, lush violins, vihuela, guitarrón, requinto, slow 6/8 feel, cinematic build, polished contemporary production, melancholic, Spanish',unistr('[Intro]\u000a(trompetas)\u000a\u000a[Verse 1]\u000aDicen en el pueblo que te fuiste,\u000aque ni la puerta cerraste al salir.\u000aDejaste tu vestido en la silla,\u000atu café a la mitad, sin despedir.\u000aY yo que te di todo, mujer,\u000ame dejaste hablando con la pared.\u000a\u000a[Pre-Chorus]\u000aTodos me preguntan si hay otro,\u000asi te cansaste de este pobre loco.\u000a\u000a[Chorus]\u000aTe fuiste sin avisar,\u000asin una carta, sin un adiós,\u000ay aquí me tienes tomando\u000acon el mariachi y con tu voz.\u000aTe fuiste sin avisar,\u000ay no sé a quién reclamar,\u000asi te llevaron los celos, el orgullo,\u000ao algo que yo no supe dar.\u000a\u000a[Verse 2]\u000aTu lado de la cama sigue frío,\u000atu perfume no se quiere despedir.\u000aMi madre dice que te olvide,\u000aque hay muchas que quisieran estar aquí.\u000aPero es que no entiendo, mi amor,\u000acómo te fuiste sin decirme por qué.\u000a\u000a[Chorus]\u000aTe fuiste sin avisar,\u000asin una carta, sin un adiós,\u000ay aquí me tienes tomando\u000acon el mariachi y con tu voz.\u000aTe fuiste sin avisar,\u000ay no sé a quién reclamar,\u000asi te llevaron los celos, el orgullo,\u000ao algo que yo no supe dar.\u000a\u000a[Bridge]\u000aPerdóname si hablé de traición,\u000asi dejé que el pueblo pensara en otro amor.\u000aNadie sabe que vengo al panteón\u000aa dejarte flores blancas y mi voz.\u000aNo te fuiste con nadie, lo sé,\u000ate fuiste una madrugada sin amanecer,\u000ay prefiero pensar que huiste de mí,\u000aporque duele menos que saber que ya no estás aquí.\u000a\u000a[Final Chorus]\u000aTe fuiste sin avisar,\u000asin una carta, sin un adiós,\u000ay aquí me tienes cantando\u000asobre tu nombre, sobre esta cruz.\u000aTe fuiste sin avisar,\u000aya no hay a quién reclamar,\u000ayo te guardo tu lado de la cama\u000apor si Dios te deja regresar.\u000a\u000a[Outro]\u000a(grito) ¡Y aquí te sigo esperando, mi reina!\u000aTe fuiste sin avisar...'),0,210.0,'es',NULL,NULL,'done','',NULL,'cacb4f5b-580c-4b24-9611-0592891c934b.mp3',65,'E minor','4',NULL,1788891177437,1789070718771,NULL,NULL,NULL,'cacb4f5b-580c-4b24-9611-0592891c934b.raw.mp3','off',0,'8475b49e-f832-4d74-b7de-f07c90c7e751',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'d2828b78-8040-48d8-ad4d-dbedc10f2d06',0.8317999999999999839);
INSERT INTO songs VALUES('d3c0216f-9081-4b22-9b3a-39bf4471c887','3a37e41c-b2a9-4aba-9b6a-9c9c94c44c5e',0,'Laberinto de tu risa','custom','conquistar a la chica imposible, su risa, sus gustos, su pelo mono, que dificil es','reggaeton dembow beat, sub bass, saxophone, male vocals, tenor vocal register, autotuned vocals, 136 bpm, D minor, modern trap production, loud and dense',unistr('[Intro]\u000a(Ad-libs melódicos, voces dobles)\u000aEy\u000aBebe\u000aQue difícil está la movie mami\u000aYeah\u000a[Verse 1]\u000aTe miro desde lejos y se me sale el pecho\u000aTu risa tiene un brillo que a cualquiera lo deja flecho\u000aAndo en tu frecuencia buscando entrar por tu lado\u000aPero estás blindada, parece un código sin descifrado\u000aEse pelo mono cayendo sobre tu cara al sonreír\u000aCada detalle tuyo es una pieza que me hace sufrir\u000aSé tus gustos, la brisa que te gusta a las diez en la noche\u000aCon ese dembow dándole y tú ahí con toda esa cocheche\u000a[Pre-Chorus]\u000aEs un laberinto de tu risa constante\u000aCada intento se siente como una pared gigante\u000aPero el ritmo me impulsa, no quiero otra historia\u000aSolo quiero ser yo quien te robe la memoria\u000a[Chorus]\u000aQué difícil conquistarte y entrar en ese muro\u000aTu pelo mono y tu risa son mi delirio puro\u000aBuscando la clave para romper este velo\u000aContigo me pierdo, mami, debajo del cielo (yeah)\u000a[Verse 2]\u000aMe dijeron que imposible está ganarme tu afecto\u000aEn Cartagena el ambiente se siente en cada defecto\u0008risas ajenas te rodean y yo quiero ser especial\u000aNo busco dramas ni drama, solo sentirte real\u000aPipo la brisa me trae tus frases tan cortas y dulces\u000aTu estilo va por otro lado y mi corazón late pulsos\u000aPero esa base marcando el ritmo de nuestra alegría\u000aNadie entiende esta batalla que cada segundo me guía [Bridge]\u000aEs tu risa, mami, lo que a veces me rompe y crea\u000aEn ese laberinto te busco hasta que la brisa desaparezca [Outro]\u000a(Voces dobles disminuyendo)\u000aQué difícil es conquistarte… sí\u000aTu pelo mono…, yeah\u000aBajo el dembow se pierde tu risa (…) (yeah) (ey)'),0,134.0,'es',NULL,NULL,'done','',NULL,'d3c0216f-9081-4b22-9b3a-39bf4471c887.mp3',136,'G minor','4',NULL,1788895918056,1788896290215,NULL,NULL,NULL,'d3c0216f-9081-4b22-9b3a-39bf4471c887.raw.mp3','off',0,'77abb979-61a8-4c05-8f84-44affd474988',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,NULL,NULL);
