INSERT INTO songs VALUES('e236b5f7-fa6b-4d37-8bb2-e67fd65eb911','8e1d83ca-c334-4fd9-834f-cf197871b147',0,'No Me Muero en la Sombra','custom','','alternative rock, tense clean guitars building into heavy distortion, driving powerful drums, anthemic chorus, dark contained verses exploding in the chorus, emotional, raw, 95 bpm, powerful female vocals, vocal range E4-F5, expressive, Spanish, female vocal, soprano voice, vocal range E4–F5, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000aNo me muero\u000aNo me muero aquí\u000a\u000a[Verse 1]\u000aCrecí en el borde de todas las fotos,\u000ala que sostiene el marco y nunca se ve.\u000aAprendí a caminar sin que sonara el suelo,\u000aa ser el eco de una voz que no era mi voz.\u000aMe hicieron pequeña y me quedé pequeña,\u000atanto tiempo en la sombra que le llamé hogar.\u000a\u000a[Pre-Chorus]\u000aY hoy la sombra me queda estrecha,\u000ahay algo aquí dentro que golpea la pared.\u000a\u000a[Chorus]\u000aNo me muero en la sombra,\u000ano me muero aquí,\u000aaunque salga arrastrándome,\u000aaunque la luz me duela al respirar.\u000aRota, con las manos rotas,\u000apero no me quedo,\u000ano me quedo a mirar.\u000a\u000a[Verse 2]\u000aTengo grietas con nombre y con fecha,\u000aun colchón que me pesa como una tumba de sal.\u000aLos años se me fueron mirando desde el borde\u000acómo vuelan los otros, cómo aprenden a amar.\u000aNo vengo a decir que ya estoy curada,\u000avengo a decir que respiro y me voy a levantar.\u000a\u000a[Pre-Chorus]\u000aY la sombra me grita que vuelva,\u000ay por primera vez le digo que no.\u000a\u000a[Chorus]\u000aNo me muero en la sombra,\u000ano me muero aquí,\u000aaunque salga arrastrándome,\u000aaunque la luz me duela al respirar.\u000aRota, con las manos rotas,\u000apero no me quedo,\u000ano me quedo a mirar.\u000a\u000a[Bridge]\u000aHubo noches en que pedí no despertar,\u000ay desperté lo mismo, y nadie lo notó.\u000aNadie vino a buscarme, nadie preguntó,\u000ay algo dentro siguió latiendo sin permiso.\u000aSi nadie enciende la luz,\u000ala enciendo yo.\u000a\u000a[Chorus]\u000a¡No me muero en la sombra!\u000a¡No me muero aquí!\u000aAunque salga arrastrándome,\u000aaunque la luz me queme al respirar.\u000aRota, con las manos rotas,\u000apero camino,\u000apor fin voy a caminar.\u000a\u000a[Outro]\u000aNo me muero, no me muero\u000aUn paso más, un paso más\u000aNo me muero aquí'),0,180.0,'es',NULL,NULL,'done','',NULL,'e236b5f7-fa6b-4d37-8bb2-e67fd65eb911.mp3',50,'B♭ major','4',NULL,1789004521896,1789005043852,NULL,NULL,NULL,'e236b5f7-fa6b-4d37-8bb2-e67fd65eb911.raw.mp3','off',0,'25e4a789-ff12-40b4-8352-a253a04dc300',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'104fc433-13a5-46cc-8d01-58bea0298ad3',0.8529999999999999805);
INSERT INTO songs VALUES('c52e6c02-30bd-466a-876f-68b9fbab8b96','8e1d83ca-c334-4fd9-834f-cf197871b147',1,'No Me Muero en la Sombra','custom','','alternative rock, tense clean guitars building into heavy distortion, driving powerful drums, anthemic chorus, dark contained verses exploding in the chorus, emotional, raw, 95 bpm, powerful female vocals, vocal range E4-F5, expressive, Spanish, female vocal, soprano voice, vocal range E4–F5, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000aNo me muero\u000aNo me muero aquí\u000a\u000a[Verse 1]\u000aCrecí en el borde de todas las fotos,\u000ala que sostiene el marco y nunca se ve.\u000aAprendí a caminar sin que sonara el suelo,\u000aa ser el eco de una voz que no era mi voz.\u000aMe hicieron pequeña y me quedé pequeña,\u000atanto tiempo en la sombra que le llamé hogar.\u000a\u000a[Pre-Chorus]\u000aY hoy la sombra me queda estrecha,\u000ahay algo aquí dentro que golpea la pared.\u000a\u000a[Chorus]\u000aNo me muero en la sombra,\u000ano me muero aquí,\u000aaunque salga arrastrándome,\u000aaunque la luz me duela al respirar.\u000aRota, con las manos rotas,\u000apero no me quedo,\u000ano me quedo a mirar.\u000a\u000a[Verse 2]\u000aTengo grietas con nombre y con fecha,\u000aun colchón que me pesa como una tumba de sal.\u000aLos años se me fueron mirando desde el borde\u000acómo vuelan los otros, cómo aprenden a amar.\u000aNo vengo a decir que ya estoy curada,\u000avengo a decir que respiro y me voy a levantar.\u000a\u000a[Pre-Chorus]\u000aY la sombra me grita que vuelva,\u000ay por primera vez le digo que no.\u000a\u000a[Chorus]\u000aNo me muero en la sombra,\u000ano me muero aquí,\u000aaunque salga arrastrándome,\u000aaunque la luz me duela al respirar.\u000aRota, con las manos rotas,\u000apero no me quedo,\u000ano me quedo a mirar.\u000a\u000a[Bridge]\u000aHubo noches en que pedí no despertar,\u000ay desperté lo mismo, y nadie lo notó.\u000aNadie vino a buscarme, nadie preguntó,\u000ay algo dentro siguió latiendo sin permiso.\u000aSi nadie enciende la luz,\u000ala enciendo yo.\u000a\u000a[Chorus]\u000a¡No me muero en la sombra!\u000a¡No me muero aquí!\u000aAunque salga arrastrándome,\u000aaunque la luz me queme al respirar.\u000aRota, con las manos rotas,\u000apero camino,\u000apor fin voy a caminar.\u000a\u000a[Outro]\u000aNo me muero, no me muero\u000aUn paso más, un paso más\u000aNo me muero aquí'),0,180.0,'es',NULL,NULL,'done','',NULL,'c52e6c02-30bd-466a-876f-68b9fbab8b96.mp3',50,'B♭ major','4',NULL,1789004521896,1789070648060,NULL,NULL,NULL,'c52e6c02-30bd-466a-876f-68b9fbab8b96.raw.mp3','clear',1,'25e4a789-ff12-40b4-8352-a253a04dc300','adc7e905-ef98-4b20-9a67-cf18909ff2e6',NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'104fc433-13a5-46cc-8d01-58bea0298ad3',0.8360999999999999544);
INSERT INTO songs VALUES('a068565b-596b-4eb9-b79b-b0d819a84610','da69eeda-1076-4880-a034-f663d725517a',0,'Sangre de Taller','custom','','female-fronted nu metal, powerful female vocals, female singer, woman singing lead, downtuned syncopated guitar riffs, thick distorted bass, heavy groove drums, quiet-loud dynamics, female rap verses, huge anthemic sung chorus, gritty, 95 bpm, Spanish, female vocal, soprano voice, vocal range E4–F5, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000aMuerde\u000aMuerde antes de pedir permiso\u000a\u000a[Verse 1]\u000aEl taller olía a grasa y a hierro viejo,\u000asus manos eran mapas de cicatrices abiertas.\u000aYo llegaba llorando y buscaba su voz ronca,\u000ame sentaba en el banco y me hablaba sin rodeos:\u000ano bajes la cabeza, ten hambre de vida,\u000aque nadie te domestique ni te apague el instinto.\u000a\u000a[Pre-Chorus]\u000aY si el mundo te aprieta la garganta,\u000atú aprieta más fuerte los dientes.\u000a\u000a[Chorus]\u000aSoy fuerte porque él me hizo así,\u000arebelde y voraz, con su sangre en las venas.\u000aNo voy a pedir perdón por lo que soy,\u000alo que él sembró no se rinde, sigue aquí.\u000aMuerde antes de pedir permiso,\u000amuerde antes de pedir permiso.\u000a\u000a[Verse 2]\u000aEl mundo me tendió la mano para amansarme,\u000ame dijeron calla, sonríe, cabe en este molde.\u000aMe probaron collares de todos los tamaños,\u000ay me acordé de sus ojos y enseñé los dientes.\u000aNo llevo más cadenas que las que yo me pongo,\u000ano le rezo a nadie que no se ensucie las manos.\u000a\u000a[Pre-Chorus]\u000aY si el mundo me aprieta la garganta,\u000ayo aprieto más fuerte los dientes.\u000a\u000a[Chorus]\u000aSoy fuerte porque él me hizo así,\u000arebelde y voraz, con su sangre en las venas.\u000aNo voy a pedir perdón por lo que soy,\u000alo que él sembró no se rinde, sigue aquí.\u000aMuerde antes de pedir permiso,\u000amuerde antes de pedir permiso.\u000a\u000a[Bridge]\u000aYa no estás, viejo, y tu voz todavía retumba,\u000ale hablo al hueco que dejaste en la cocina.\u000aSigo de pie, sigo mordiendo, sigo entera,\u000alo que sembraste en mí se niega a morir.\u000aTu lección es mi armadura,\u000atu apellido es mi bandera.\u000a\u000a[Chorus]\u000a¡Soy fuerte porque él me hizo así!\u000a¡Rebelde y voraz, con su sangre en las venas!\u000aNo voy a pedir perdón por lo que soy,\u000alo que él sembró no se rinde, sigue aquí.\u000a\u000a[Outro]\u000aMuerde antes de pedir permiso,\u000amuerde, y no pidas permiso.'),0,180.0,'es',NULL,NULL,'done','',NULL,'a068565b-596b-4eb9-b79b-b0d819a84610.mp3',200,'B♭ minor','4',NULL,1789006156414,1789070502529,NULL,NULL,NULL,'a068565b-596b-4eb9-b79b-b0d819a84610.raw.mp3','clear',1,'25e4a789-ff12-40b4-8352-a253a04dc300','adc7e905-ef98-4b20-9a67-cf18909ff2e6',NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'104fc433-13a5-46cc-8d01-58bea0298ad3',0.8172000000000000374);
