INSERT INTO songs VALUES('b053aabb-a93c-43c7-8ffb-a8c8fa5e7d33','d7138a71-91fb-4754-9d82-eeb78101a869',3,'Lo Más Hondo','custom','','female-fronted alternative rock ballad, powerful raspy female vocals, female singer, woman singing lead, clean tense guitars building into heavy distortion, big emotional drums, soaring anthemic chorus, vulnerable intimate bridge, emotional, 82 bpm, female vocal, soprano voice, vocal range E4–F5, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000a\u000a[Verse 1]\u000aTu taza sigue a la izquierda de la mesa,\u000ala cuchara azul, el café hasta el borde.\u000aHay un pelo tuyo en la trama del sillón\u000ay no lo quito, que se quede donde estorbe.\u000a\u000a[Pre-Chorus]\u000aEl silencio en esta casa tiene dientes,\u000amuerde cada esquina donde ya no estás.\u000a\u000a[Chorus]\u000aMe llegaste a lo más hondo y ahí mismo te fuiste,\u000ame abriste el pecho y dejaste la puerta abierta.\u000aNadie me enseñó a vivir con lo que rompiste,\u000ame partí en dos y ninguna mitad despierta.\u000aNo me curo, no me curo,\u000ame rompiste donde nadie más llegó.\u000a\u000a[Verse 2]\u000aTus llaves siguen colgadas junto a la puerta,\u000ael abrigo con la forma de tus hombros.\u000aCogías el camino largo cuando llovía,\u000aahora miro los cristales y te nombro.\u000a\u000a[Pre-Chorus]\u000aEl silencio en esta casa tiene dientes,\u000ay te grito y no contesta nadie más.\u000a\u000a[Chorus]\u000aMe llegaste a lo más hondo y ahí mismo te fuiste,\u000ame abriste el pecho y dejaste la puerta abierta.\u000aNadie me enseñó a vivir con lo que rompiste,\u000ame partí en dos y ninguna mitad despierta.\u000aNo me curo, no me curo,\u000ame rompiste donde nadie más llegó.\u000a\u000a[Bridge]\u000aTu risa en el pasillo,\u000alos libros mal apilados,\u000atodo se hizo añicos sin hacer ruido.\u000aNo lo voy a recomponer,\u000ahay roturas que se quedan,\u000ay esta es mía, es lo que queda de ti.\u000a\u000a[Chorus]\u000aMe llegaste a lo más hondo y ahí mismo te fuiste,\u000ame abriste el pecho y dejaste la puerta abierta.\u000aNadie me enseñó a vivir con lo que rompiste,\u000ame partí en dos y ninguna mitad despierta.\u000aNo me curo, no me curo,\u000ame rompiste donde nadie más llegó.\u000a\u000a[Outro]\u000aLa herida abierta es un mapa sobre el pecho,\u000ano la cierro, no la cierro:\u000aes el precio de haberte querido tanto.'),0,219.0,'es',NULL,NULL,'done','',NULL,'b053aabb-a93c-43c7-8ffb-a8c8fa5e7d33.mp3',80,'E♭ minor','4',NULL,1789007958577,1789008395241,NULL,NULL,NULL,'b053aabb-a93c-43c7-8ffb-a8c8fa5e7d33.raw.mp3','off',0,'25e4a789-ff12-40b4-8352-a253a04dc300',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'104fc433-13a5-46cc-8d01-58bea0298ad3',0.8496000000000000218);
INSERT INTO songs VALUES('c57a1182-6b5b-4f1a-96a4-eb264231cfa4','e4067eac-38c5-4640-b780-d3d31e0a0c2f',0,'Instagrameando','custom','','reggaeton, dembow beat, reggae guitar skank, dancehall, tropical, warm male vocals, smooth melodic flow, catchy singalong chorus, deep bass, upbeat, romantic, sunny, party night, 94 bpm, male vocal, tenor voice, vocal range G3–E4, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000aTe vi primero en la pantalla, mor.\u000aY hoy te tengo aquí bailando.\u000a\u000a[Verse 1]\u000aMedia noche y yo pegado al celular,\u000aInstagrameando sin nada que buscar.\u000aY de repente sale tu foto en la playa,\u000aCon esa risa, parce, que a uno lo desmaya.\u000aLe di like a todo, hasta a la del dos mil veinte,\u000aMe vi tus historias como quince veces seguidas.\u000aMe enamoré de ti sin haberte conocido,\u000aY no me atreví a escribirte ni un "hola, ¿cómo has estado?".\u000a\u000a[Pre-Chorus]\u000aLa pantalla se apagaba y tú seguías ahí,\u000aYo soñando con la farra donde te iba a ver a ti.\u000a\u000a[Chorus]\u000aTe encontré instagrameando y ahora estás aquí,\u000aBailando pegadita, mor, bailando junto a mí.\u000aDel like a tu cintura, de la foto a tu piel,\u000aQue suene ese dembow y que no pare hasta amanecer.\u000aTe encontré instagrameando y hoy te tengo aquí,\u000aBailando toda la noche, mor, bailando junto a mí.\u000a\u000a[Verse 2]\u000aSábado de farra con los parceros por el barrio,\u000aUn trago en la mano y el dembow sonando a diario.\u000aY ahí estabas tú, más linda que en cualquier foto,\u000aSe me olvidó el celular y hasta el nombre del sitio.\u000aMe acerqué despacio y te dije, muerto de risa:\u000a"Yo te conozco de Instagram, te sigo hace unos días".\u000aTe reíste, mor, y me dijiste "ya lo sabía",\u000aQue los likes a la una de la mañana no se disimulan.\u000a\u000a[Pre-Chorus]\u000aLa pantalla se apagó y tú seguiste ahí,\u000aYa no era un sueño, mor, la farra era pa'' mí.\u000a\u000a[Chorus]\u000aTe encontré instagrameando y ahora estás aquí,\u000aBailando pegadita, mor, bailando junto a mí.\u000aDel like a tu cintura, de la foto a tu piel,\u000aQue suene ese dembow y que no pare hasta amanecer.\u000aTe encontré instagrameando y hoy te tengo aquí,\u000aBailando toda la noche, mor, bailando junto a mí.\u000a\u000a[Bridge]\u000aCelular apagado, ya no hace falta,\u000aQue lo que yo quería ver lo tengo en la pista.\u000aBaila, mor, baila, que ya está saliendo el sol,\u000aY esta noche, parce, es la mejor de las dos.\u000aBaila, mor, baila... hasta que salga el sol.\u000a\u000a[Chorus]\u000aTe encontré instagrameando y ahora estás aquí,\u000aBailando pegadita, mor, bailando junto a mí.\u000aDel like a tu cintura, de la foto a tu piel,\u000aQue suene ese dembow y que no pare hasta amanecer.\u000a\u000a[Outro]\u000aTe vi primero en la pantalla, mor.\u000aY hoy te tengo aquí bailando.\u000aHasta que salga el sol.'),0,190.0,'es',NULL,NULL,'done','',NULL,'c57a1182-6b5b-4f1a-96a4-eb264231cfa4.mp3',190,'C major','4',NULL,1789010500799,1789011276898,NULL,NULL,NULL,'c57a1182-6b5b-4f1a-96a4-eb264231cfa4.raw.mp3','clear',1,'a9137dae-4b01-433f-9f1a-7796c6d4bb60',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'0f126be2-f06f-4e47-9e85-e4b0476d62b6',0.8296999999999999931);
