INSERT INTO songs VALUES('871200bd-5c73-4a83-bfb7-280ea5775adf','a044a8a0-320e-43b1-8639-d5eb286e8436',0,'Tres Vidas','custom','','hard reggaeton, heavy dembow beat, perreo groove, punchy 808 sub bass, reggae guitar skank accents, latin percussion, warm male vocals, energetic melodic flow, catchy singalong chorus, building tension bridge, explosive drop chorus, club banger, party night, 98 bpm, male vocal, tenor voice, vocal range G3–E4, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000aTres vidas, mor.\u000aY en ninguna me alcanza la noche.\u000a\u000a[Verse 1]\u000aLunes con la novia, cine y helado en el parque,\u000aMe dice "mi amor" y yo le juro que es la única, parce.\u000aMiércoles con la amante en un hotel de la setenta,\u000aCelular en silencio, que nadie se dé cuenta.\u000aY el viernes llego a casa con flores pa'' mi esposa,\u000aLe digo "estaba en la oficina", ella sonríe y no dice cosa.\u000aTres nombres en el pecho, tres chats con candado,\u000aTres perfumes distintos y yo siempre bien bañado.\u000a\u000a[Pre-Chorus]\u000aUna me quiere, otra me tiene,\u000aY la otra sabe todo pero no me lo dice.\u000aEl dembow va subiendo y la mentira crece,\u000aTres vidas, parce, y no me alcanzan los meses.\u000a\u000a[Chorus]\u000aTengo tres vidas y las tres van a bailar,\u000aUna pa'' la novia, otra pa'' la amante y otra pa'' la del altar.\u000aTengo tres vidas y ninguna puede parar,\u000aQue suene el dembow duro, que las tres quieren perrear.\u000aTres vidas, mor, tres vidas,\u000aY en cada una me muero y en cada una revivo.\u000a\u000a[Verse 2]\u000aLa novia me pregunta que por qué huelo a coco,\u000aLa amante que por qué le contesto tan poco.\u000aY la esposa me mira mientras sirve el almuerzo,\u000aCon esa calma, parce, que da más miedo que un tuerto.\u000aMe cambio de camisa en el carro antes de subir,\u000aMe sé tres cumpleaños y tres formas de mentir.\u000aVivo corriendo, mor, del norte hasta el sur,\u000aY todavía no sé cuál de las tres es mi luz.\u000a\u000a[Pre-Chorus]\u000aUna me quiere, otra me tiene,\u000aY la otra sabe todo pero no me lo dice.\u000aEl dembow va subiendo y la mentira crece,\u000aTres vidas, parce, y no me alcanzan los meses.\u000a\u000a[Chorus]\u000aTengo tres vidas y las tres van a bailar,\u000aUna pa'' la novia, otra pa'' la amante y otra pa'' la del altar.\u000aTengo tres vidas y ninguna puede parar,\u000aQue suene el dembow duro, que las tres quieren perrear.\u000aTres vidas, mor, tres vidas,\u000aY en cada una me muero y en cada una revivo.\u000a\u000a[Bridge]\u000aSábado en la disco, yo bailando tranquilo,\u000aY por la puerta entra la novia con sus amigas.\u000aDiez minutos después la amante por el otro lado,\u000aY mi esposa en la barra pidiendo un trago.\u000aLas tres en la misma pista, las tres mirando pa'' acá,\u000aY el DJ, parce, sube el volumen pa'' rematar.\u000aSe apagan las luces... y va a explotar.\u000a\u000a[Drop]\u000a¡Tres vidas!\u000a¡Y las tres en la misma pista!\u000a¡Tres vidas!\u000a¡Y esta noche se me acaban las tres!\u000a¡Baila, baila, baila!\u000a¡Que mañana no sé dónde voy a dormir!\u000a\u000a[Chorus]\u000aTengo tres vidas y las tres van a bailar,\u000aUna pa'' la novia, otra pa'' la amante y otra pa'' la del altar.\u000aTengo tres vidas y ninguna puede parar,\u000aQue suene el dembow duro, que las tres quieren perrear.\u000a\u000a[Outro]\u000aTres vidas, mor.\u000aY ahora ninguna.\u000aPero qué buena farra.'),0,210.0,'es',NULL,NULL,'done','',NULL,'871200bd-5c73-4a83-bfb7-280ea5775adf.mp3',NULL,'E♭ major','4',NULL,1789012252526,1789014824228,NULL,NULL,NULL,'871200bd-5c73-4a83-bfb7-280ea5775adf.raw.mp3','off',0,'a9137dae-4b01-433f-9f1a-7796c6d4bb60',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'0f126be2-f06f-4e47-9e85-e4b0476d62b6',0.8659999999999999921);
INSERT INTO songs VALUES('3c2127bb-87e2-4828-9f9a-bd89c6947638','a044a8a0-320e-43b1-8639-d5eb286e8436',2,'Tres Vidas','custom','','hard reggaeton, heavy dembow beat, perreo groove, punchy 808 sub bass, reggae guitar skank accents, latin percussion, warm male vocals, energetic melodic flow, catchy singalong chorus, building tension bridge, explosive drop chorus, club banger, party night, 98 bpm, male vocal, tenor voice, vocal range G3–E4, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000aTres vidas, mor.\u000aY en ninguna me alcanza la noche.\u000a\u000a[Verse 1]\u000aLunes con la novia, cine y helado en el parque,\u000aMe dice "mi amor" y yo le juro que es la única, parce.\u000aMiércoles con la amante en un hotel de la setenta,\u000aCelular en silencio, que nadie se dé cuenta.\u000aY el viernes llego a casa con flores pa'' mi esposa,\u000aLe digo "estaba en la oficina", ella sonríe y no dice cosa.\u000aTres nombres en el pecho, tres chats con candado,\u000aTres perfumes distintos y yo siempre bien bañado.\u000a\u000a[Pre-Chorus]\u000aUna me quiere, otra me tiene,\u000aY la otra sabe todo pero no me lo dice.\u000aEl dembow va subiendo y la mentira crece,\u000aTres vidas, parce, y no me alcanzan los meses.\u000a\u000a[Chorus]\u000aTengo tres vidas y las tres van a bailar,\u000aUna pa'' la novia, otra pa'' la amante y otra pa'' la del altar.\u000aTengo tres vidas y ninguna puede parar,\u000aQue suene el dembow duro, que las tres quieren perrear.\u000aTres vidas, mor, tres vidas,\u000aY en cada una me muero y en cada una revivo.\u000a\u000a[Verse 2]\u000aLa novia me pregunta que por qué huelo a coco,\u000aLa amante que por qué le contesto tan poco.\u000aY la esposa me mira mientras sirve el almuerzo,\u000aCon esa calma, parce, que da más miedo que un tuerto.\u000aMe cambio de camisa en el carro antes de subir,\u000aMe sé tres cumpleaños y tres formas de mentir.\u000aVivo corriendo, mor, del norte hasta el sur,\u000aY todavía no sé cuál de las tres es mi luz.\u000a\u000a[Pre-Chorus]\u000aUna me quiere, otra me tiene,\u000aY la otra sabe todo pero no me lo dice.\u000aEl dembow va subiendo y la mentira crece,\u000aTres vidas, parce, y no me alcanzan los meses.\u000a\u000a[Chorus]\u000aTengo tres vidas y las tres van a bailar,\u000aUna pa'' la novia, otra pa'' la amante y otra pa'' la del altar.\u000aTengo tres vidas y ninguna puede parar,\u000aQue suene el dembow duro, que las tres quieren perrear.\u000aTres vidas, mor, tres vidas,\u000aY en cada una me muero y en cada una revivo.\u000a\u000a[Bridge]\u000aSábado en la disco, yo bailando tranquilo,\u000aY por la puerta entra la novia con sus amigas.\u000aDiez minutos después la amante por el otro lado,\u000aY mi esposa en la barra pidiendo un trago.\u000aLas tres en la misma pista, las tres mirando pa'' acá,\u000aY el DJ, parce, sube el volumen pa'' rematar.\u000aSe apagan las luces... y va a explotar.\u000a\u000a[Drop]\u000a¡Tres vidas!\u000a¡Y las tres en la misma pista!\u000a¡Tres vidas!\u000a¡Y esta noche se me acaban las tres!\u000a¡Baila, baila, baila!\u000a¡Que mañana no sé dónde voy a dormir!\u000a\u000a[Chorus]\u000aTengo tres vidas y las tres van a bailar,\u000aUna pa'' la novia, otra pa'' la amante y otra pa'' la del altar.\u000aTengo tres vidas y ninguna puede parar,\u000aQue suene el dembow duro, que las tres quieren perrear.\u000a\u000a[Outro]\u000aTres vidas, mor.\u000aY ahora ninguna.\u000aPero qué buena farra.'),0,210.0,'es',NULL,NULL,'done','',NULL,'3c2127bb-87e2-4828-9f9a-bd89c6947638.mp3',NULL,'E♭ major','4',NULL,1789012252526,1789012464038,NULL,NULL,NULL,'3c2127bb-87e2-4828-9f9a-bd89c6947638.raw.mp3','off',0,'a9137dae-4b01-433f-9f1a-7796c6d4bb60',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'0f126be2-f06f-4e47-9e85-e4b0476d62b6',0.8577000000000000179);
