INSERT INTO songs VALUES('2d34ba41-2a87-412c-b3f0-100701d2f481','503c0cca-509b-4e26-855f-2d033790f639',0,'La Manillita','custom','','reggaeton, dembow beat, reggae guitar skank, dancehall, tropical, warm male vocals, smooth melodic flow, nostalgic and heartfelt, catchy singalong chorus, melodic ad-libs, deep bass, laid-back, sunny, 90 bpm, male vocal, tenor voice, vocal range G3–E4, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000aLa manillita, mor.\u000aTodavía la tengo, ve.\u000a\u000a[Verse 1]\u000aDomingo en la piedra,\u000ael agua verde abajo,\u000atu mano en mi muñeca\u000ay un hilo por regalo.\u000aMe la amarraste riendo,\u000acon un nudito, mor,\u000ayo pensé que era un detalle\u000ay es lo único que quedó.\u000a\u000a[Pre-Chorus]\u000aLas fotos se borraron,\u000alos chats también,\u000apero el hilo no,\u000apero el hilo no.\u000a\u000a[Chorus]\u000aLa manillita, mor,\u000ala que me diste en Guatapé,\u000ase puso vieja, yo también,\u000ay sigue aquí, mírala, ve.\u000aLa manillita, mor,\u000aun nudo que no se soltó,\u000atú te fuiste y ella no,\u000ay en mi muñeca sigues vos.\u000a\u000a[Post-Chorus]\u000aMírala, ve, mírala, ve,\u000ala manillita de Guatapé.\u000aMírala, ve, mírala, ve,\u000aeh-eh, eh-eh.\u000a\u000a[Verse 2]\u000aVuelvo a Guatapé,\u000alos zócalos de colores,\u000ala señora en la esquina\u000avendiendo hilos y flores.\u000aMiro mi muñeca\u000ay te veo otra vez,\u000averde y azul, mor,\u000acomo aquel atardecer.\u000a\u000a[Pre-Chorus]\u000aLas fotos se borraron,\u000alos chats también,\u000apero el hilo no,\u000apero el hilo no.\u000a\u000a[Chorus]\u000aLa manillita, mor,\u000ala que me diste en Guatapé,\u000ase puso vieja, yo también,\u000ay sigue aquí, mírala, ve.\u000aLa manillita, mor,\u000aun nudo que no se soltó,\u000atú te fuiste y ella no,\u000ay en mi muñeca sigues vos.\u000a\u000a[Bridge]\u000aDicen que si se rompe\u000ase cumple un deseo, mor,\u000apor eso yo la cuido,\u000apor eso no la suelto, no.\u000aY si se rompe un día\u000apediría verte aquí,\u000aen Guatapé otra vez,\u000acontigo, mor, otra vez.\u000a\u000a[Chorus]\u000aLa manillita, mor,\u000ala que me diste en Guatapé,\u000ase puso vieja, yo también,\u000ay sigue aquí, mírala, ve.\u000a\u000a[Post-Chorus]\u000aMírala, ve, mírala, ve,\u000ala manillita de Guatapé.\u000aMírala, ve, mírala, ve,\u000aeh-eh, eh-eh.\u000a\u000a[Outro]\u000aLa manillita, mor.\u000aVerde y azul, Guatapé.\u000aTodavía la tengo, ve.'),0,164.0,'es',NULL,NULL,'done','',NULL,'2d34ba41-2a87-412c-b3f0-100701d2f481.mp3',100,'B♭ major','4',NULL,1789015549773,1789016006429,NULL,NULL,NULL,'2d34ba41-2a87-412c-b3f0-100701d2f481.raw.mp3','off',0,'a9137dae-4b01-433f-9f1a-7796c6d4bb60',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'0f126be2-f06f-4e47-9e85-e4b0476d62b6',0.7831000000000000182);
