INSERT INTO songs VALUES('b1a83ca0-2533-48b6-907a-c40db7baef9d','4d16c62f-6305-486d-a626-fc1fba6dc5ff',0,'De Isla en Isla','custom','','reggaeton, dembow beat, reggae guitar skank, dancehall, tropical, steel drum accents, warm male vocals, smooth melodic flow, feel-good summer vibe, catchy singalong chorus, melodic ad-libs, deep bass, laid-back, sunny, 94 bpm, male vocal, tenor voice, vocal range G3–E4, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000aDe isla en isla, mor.\u000aContigo y el mar.\u000a\u000a[Verse 1]\u000aUn tiquete y tu maleta,\u000ael celular en modo avión,\u000abajamos a la arena\u000ay ya cambió el color.\u000aMar de siete colores,\u000atu bikini y mi sombrero,\u000aun coco con hielito\u000ay el reloj en cero.\u000a\u000a[Pre-Chorus]\u000aNo hay lunes, no hay afán,\u000asolo sal y sol,\u000aque nos lleve la marea,\u000aSebas Marea, mor.\u000a\u000a[Chorus]\u000aDe isla en isla, mor,\u000acontigo y el mar,\u000aSan Andrés, Providencia,\u000ay no queremos parar.\u000aDe isla en isla, mor,\u000ala brisa y el ron,\u000aun sol que no se apaga\u000ay tú en mi corazón.\u000a\u000a[Post-Chorus]\u000aEh-oh, eh-oh,\u000ade isla en isla, mor.\u000aEh-oh, eh-oh,\u000ala brisa y el ron.\u000a\u000a[Verse 2]\u000aProvidencia en botecito,\u000aCartagena en el balcón,\u000aAruba, tu pelo suelto,\u000aCurazao de color.\u000aBailamos en la arena,\u000adescalzos, mor, los dos,\u000ala luna nos alumbra\u000ay el mar es el dembow.\u000a\u000a[Pre-Chorus]\u000aNo hay lunes, no hay afán,\u000asolo sal y sol,\u000aque nos lleve la marea,\u000aSebas Marea, mor.\u000a\u000a[Chorus]\u000aDe isla en isla, mor,\u000acontigo y el mar,\u000aSan Andrés, Providencia,\u000ay no queremos parar.\u000aDe isla en isla, mor,\u000ala brisa y el ron,\u000aun sol que no se apaga\u000ay tú en mi corazón.\u000a\u000a[Bridge]\u000aY si se acaba la plata,\u000anos quedamos por acá,\u000avendiendo cocos, mor,\u000amirando el mar.\u000aDe isla en isla,\u000ade isla en isla,\u000ade isla en isla, mor,\u000acontigo y el mar.\u000a\u000a[Chorus]\u000aDe isla en isla, mor,\u000acontigo y el mar,\u000aSan Andrés, Providencia,\u000ay no queremos parar.\u000a\u000a[Post-Chorus]\u000aEh-oh, eh-oh,\u000ade isla en isla, mor.\u000aEh-oh, eh-oh,\u000ala brisa y el ron.\u000a\u000a[Outro]\u000aDe isla en isla, mor.\u000aContigo y el mar.\u000aEh-oh, eh-oh.'),0,180.0,'es',NULL,NULL,'done','',NULL,'b1a83ca0-2533-48b6-907a-c40db7baef9d.mp3',NULL,'C major','4',NULL,1789047641470,1789047830478,NULL,NULL,NULL,'b1a83ca0-2533-48b6-907a-c40db7baef9d.raw.mp3','off',0,'a9137dae-4b01-433f-9f1a-7796c6d4bb60',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'0f126be2-f06f-4e47-9e85-e4b0476d62b6',0.7440999999999999837);
