INSERT INTO songs VALUES('a57d876e-74e3-469c-8d86-e7a82a4f83f1','ae0d8c9f-4518-44ed-981d-6c59c732d1ea',0,'El Bote','custom','','reggaeton, slow sensual dembow beat, reggae guitar skank, tropical, warm male vocals, smooth melodic flow, sensual and intimate, night beach vibe, catchy singalong chorus, melodic ad-libs, deep bass, laid-back, 88 bpm, male vocal, tenor voice, vocal range G3–E4, bright vocal timbre, clean vocals, light airy voice',unistr('[Intro]\u000aNos escapamos, mor.\u000aLa playa es de los dos.\u000a\u000a[Verse 1]\u000aMedianoche y sin zapatos,\u000ala arena está tibia,\u000atú corriendo por la orilla\u000ay yo detrás de tu risa.\u000aMe tiras agua en la cara,\u000ate alcanzo y no te suelto,\u000ala luna mira de lejos\u000ay el mar guarda el secreto.\u000a\u000a[Pre-Chorus]\u000aY ahí, entre las palmas,\u000aun bote sin dueño, mor,\u000ala madera vieja\u000ay tú y yo y el calor.\u000a\u000a[Chorus]\u000aEn el bote, mor,\u000ahasta que salga el sol,\u000atu piel con sal y arena\u000ay yo pegado a tu calor.\u000aEn el bote, mor,\u000aque se mueva con los dos,\u000aque nos meza la marea\u000ay no nos suelte, no.\u000a\u000a[Post-Chorus]\u000aOh-oh, oh-oh,\u000aen el bote, mor.\u000aOh-oh, oh-oh,\u000ahasta que salga el sol.\u000a\u000a[Verse 2]\u000aTu vestido en la proa,\u000ami camisa en el timón,\u000ala madera cruje, mor,\u000aal compás de este dembow.\u000aMe hablas al oído,\u000abajito, sin voz,\u000ay el mar rompe fuerte\u000apa'' tapar a los dos.\u000a\u000a[Pre-Chorus]\u000aY ahí, entre las palmas,\u000aun bote sin dueño, mor,\u000ala madera vieja\u000ay tú y yo y el calor.\u000a\u000a[Chorus]\u000aEn el bote, mor,\u000ahasta que salga el sol,\u000atu piel con sal y arena\u000ay yo pegado a tu calor.\u000aEn el bote, mor,\u000aque se mueva con los dos,\u000aque nos meza la marea\u000ay no nos suelte, no.\u000a\u000a[Bridge]\u000aQue amanezca, que amanezca,\u000ay no quiero salir,\u000aque este bote se hunda,\u000apero contigo aquí.\u000aQue amanezca, que amanezca,\u000aque el sol nos vea así.\u000a\u000a[Chorus]\u000aEn el bote, mor,\u000ahasta que salga el sol,\u000atu piel con sal y arena\u000ay yo pegado a tu calor.\u000a\u000a[Post-Chorus]\u000aOh-oh, oh-oh,\u000aen el bote, mor.\u000aOh-oh, oh-oh,\u000ahasta que salga el sol.\u000a\u000a[Outro]\u000aEn el bote, mor.\u000aHasta que salga el sol.\u000aOh-oh, oh-oh.'),0,158.0,'es',NULL,NULL,'done','',NULL,'a57d876e-74e3-469c-8d86-e7a82a4f83f1.mp3',30,'C major','4',NULL,1789058569528,1789058721377,NULL,NULL,NULL,'a57d876e-74e3-469c-8d86-e7a82a4f83f1.raw.mp3','off',0,'a9137dae-4b01-433f-9f1a-7796c6d4bb60',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'0f126be2-f06f-4e47-9e85-e4b0476d62b6',0.7481999999999999762);
