INSERT INTO songs VALUES('f1fefed2-4fa0-482d-8ae4-c22ec2a05b1f','3ccc0563-946a-4ed8-8ec4-a06ca5cc3606',0,'Que No Cierre la Cantina','custom','','modern mariachi, mariachi pop ballad, ranchera romántica, single male lead vocal, warm male baritone-tenor vocals with emotional vibrato, heartfelt gritos, soaring trumpets, lush violins, vihuela, guitarrón, requinto, mid-tempo 6/8 ranchera feel, cantina at night, cinematic build, polished contemporary production, melancholic, Spanish, male vocal, tenor voice, vocal range D#3–C#4, warm vocal timbre, clean vocals',unistr('[Intro]\u000a¡Ay, ay, ay!\u000aSírvame otra, compadre.\u000a\u000a[Verse 1]\u000aSírvame otra, compadre,\u000aque la noche está empezando,\u000aque toque el mariachi fuerte,\u000aque yo aquí sigo cantando.\u000aMe dicen: qué buena vida,\u000aqué alegre, qué buen amigo,\u000ay nadie sabe que río\u000apa'' no quedarme conmigo.\u000a\u000a[Pre-Chorus]\u000aPorque cuando apagan la luz\u000ay el mariachi ya se va,\u000ame espera la casa sola\u000ay una cama sin su mitad.\u000a\u000a[Chorus]\u000aQue no cierre la cantina,\u000aque me sirvan otra más,\u000aque aquí canto, aquí me río\u000ay no me tengo que acordar.\u000aQue no cierre la cantina,\u000aque en mi casa no hay calor,\u000asolo una cama muy grande\u000ay la mitad sin su olor.\u000a\u000a[Verse 2]\u000aElla se fue un mes de marzo,\u000ase llevó hasta las cortinas,\u000adejó su lado en la cama\u000ay a mí en esta cantina.\u000aNo duermo del lado suyo,\u000ani toco su almohada,\u000ame acuesto con la ropa puesta\u000apa'' sentir que no es mi cama.\u000a\u000a[Pre-Chorus]\u000aPorque cuando apagan la luz\u000ay el mariachi ya se va,\u000ame espera la casa sola\u000ay una cama sin su mitad.\u000a\u000a[Chorus]\u000aQue no cierre la cantina,\u000aque me sirvan otra más,\u000aque aquí canto, aquí me río\u000ay no me tengo que acordar.\u000aQue no cierre la cantina,\u000aque en mi casa no hay calor,\u000asolo una cama muy grande\u000ay la mitad sin su olor.\u000a\u000a[Bridge]\u000aY cuando el último se va,\u000ael cantinero no cierra,\u000ase sirve una conmigo\u000ay mira su propia mesa.\u000aA él también lo dejaron,\u000apor eso no cierra nunca,\u000apor eso aquí no se apaga\u000ani la luz ni la música.\u000a\u000a[Chorus]\u000aQue no cierre la cantina,\u000aque me sirvan otra más,\u000aque aquí canto, aquí me río\u000ay no me tengo que acordar.\u000aQue no cierre la cantina,\u000aque en mi casa no hay calor,\u000asolo una cama muy grande\u000ay la mitad sin su olor.\u000a\u000a[Outro]\u000aSírvame otra, compadre.\u000aQue todavía no amanece.\u000a¡Ay, ay, ay!'),0,208.0,'es',NULL,NULL,'done','',NULL,'f1fefed2-4fa0-482d-8ae4-c22ec2a05b1f.mp3',68,'E minor','2',NULL,1789071421547,1789149771291,NULL,NULL,NULL,'f1fefed2-4fa0-482d-8ae4-c22ec2a05b1f.raw.mp3','off',0,'8475b49e-f832-4d74-b7de-f07c90c7e751','044143e1-87c5-4d8c-9d29-e894c24637af',NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'d2828b78-8040-48d8-ad4d-dbedc10f2d06',0.7360999999999999766);
INSERT INTO songs VALUES('cb2e8fdc-95c7-47b1-87fe-3138a02c8c55','a472f1b3-408b-42a8-ad36-4a768d2a6700',0,'Hasta Luego, Viejo','custom','','modern mariachi, mariachi pop ballad, ranchera romántica, warm male baritone-tenor vocals with emotional vibrato, heartfelt gritos, soaring trumpets, lush violins, vihuela, guitarrón, requinto, slow 6/8 feel, cinematic build, polished contemporary production, melancholic, Spanish, male vocal, tenor voice, vocal range D#3–C#4, warm vocal timbre, clean vocals',unistr('[Intro]\u000aHasta luego, viejo.\u000a\u000a[Verse 1]\u000aHoy el pueblo se vistió de negro,\u000alas campanas no quieren callar.\u000aTu sombrero quedó en el perchero,\u000atu silla en la mesa sin ocupar.\u000aY yo que aprendí de ti a ser hombre,\u000atodavía no aprendo a llorar.\u000a\u000a[Pre-Chorus]\u000aTodos vienen a darme el pésame,\u000ay yo solo quiero oírte hablar.\u000a\u000a[Chorus]\u000aHasta luego, viejo,\u000aque no me sale decir adiós,\u000ate vas con tu sombrero puesto\u000ay con la bendición de Dios.\u000aHasta luego, viejo,\u000aguárdame un lugar allá,\u000aque aquí me quedo con tus consejos\u000ay con tu nombre pa'' cantar.\u000a\u000a[Verse 2]\u000aMe enseñaste a montar y a ser derecho,\u000aa quitarme el sombrero al saludar,\u000aa tomar sin caerme, a no rendirme,\u000ay que un hombre también sabe llorar.\u000aHoy en tu tumba dejo tu tequila\u000ay un mariachi que no va a parar.\u000a\u000a[Chorus]\u000aHasta luego, viejo,\u000aque no me sale decir adiós,\u000ate vas con tu sombrero puesto\u000ay con la bendición de Dios.\u000aHasta luego, viejo,\u000aguárdame un lugar allá,\u000aque aquí me quedo con tus consejos\u000ay con tu nombre pa'' cantar.\u000a\u000a[Bridge]\u000aMi hijo me pregunta dónde estás,\u000aque por qué la casa está tan quieta.\u000aLe digo que te fuiste a descansar,\u000aque andas allá arriba en tu yegua prieta.\u000aY hoy me llamó viejo por primera vez,\u000acon tu misma voz y tu misma mirada,\u000ay entendí que no te fuiste, papá,\u000aque te quedaste en él, en mí y en esta casa.\u000a\u000a[Final Chorus]\u000aHasta luego, viejo,\u000aque no me sale decir adiós,\u000ahoy me pongo tu sombrero\u000ay le canto por los dos.\u000aHasta luego, viejo,\u000aguárdame un lugar allá,\u000aque tu nieto ya me dice viejo\u000ay yo le contesto como tú, papá.\u000a\u000a[Outro]\u000a¡Ay, mi viejo!\u000aHasta luego... no adiós.'),0,210.0,'es',NULL,NULL,'done','',NULL,'cb2e8fdc-95c7-47b1-87fe-3138a02c8c55.mp3',65,'E minor','3',NULL,1789149532920,1789152003520,NULL,NULL,NULL,'cb2e8fdc-95c7-47b1-87fe-3138a02c8c55.raw.mp3','clear',1,'8475b49e-f832-4d74-b7de-f07c90c7e751',NULL,NULL,NULL,NULL,0,'none',NULL,NULL,'',NULL,NULL,NULL,'d2828b78-8040-48d8-ad4d-dbedc10f2d06',0.7259999999999999787);
