-- Volcado de web/data/suno.db (SQLite). Restaurar: sqlite3 web/data/suno.db < db/suno.dump.sql
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE songs (
      id TEXT PRIMARY KEY,
      task_id TEXT,
      variant INTEGER NOT NULL DEFAULT 0,
      title TEXT NOT NULL,
      mode TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      style TEXT NOT NULL DEFAULT '',
      lyrics TEXT NOT NULL DEFAULT '',
      instrumental INTEGER NOT NULL DEFAULT 0,
      duration REAL,
      vocal_language TEXT NOT NULL DEFAULT 'es',
      model TEXT,
      seed TEXT,
      status TEXT NOT NULL DEFAULT 'queued',
      progress TEXT NOT NULL DEFAULT '',
      error TEXT,
      audio_file TEXT,
      bpm INTEGER,
      key_scale TEXT,
      time_signature TEXT,
      generation_info TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    , original_audio_file TEXT, voice_id TEXT, voice_job_id TEXT, raw_audio_file TEXT, master_preset TEXT NOT NULL DEFAULT 'clear', enhanced INTEGER NOT NULL DEFAULT 0, artist_id TEXT, album_id TEXT, parent_id TEXT, edit_op TEXT, edit_instruction TEXT, autotune INTEGER NOT NULL DEFAULT 0, video_status TEXT NOT NULL DEFAULT 'none', video_job_id TEXT, video_file TEXT, video_progress TEXT NOT NULL DEFAULT '', video_error TEXT, storyboard TEXT, voice_options TEXT, voice_match_id TEXT, voice_similarity REAL);
COMMIT;
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE artists (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      emoji TEXT NOT NULL DEFAULT '🎤',
      style TEXT NOT NULL DEFAULT '',
      description TEXT NOT NULL DEFAULT '',
      vocal_language TEXT NOT NULL DEFAULT 'es',
      default_voice_id TEXT,
      created_at INTEGER NOT NULL
    , image_file TEXT, image_prompt TEXT, lora_status TEXT NOT NULL DEFAULT 'none', lora_path TEXT, lora_progress TEXT NOT NULL DEFAULT '', lora_error TEXT, lora_tag TEXT, lora_adapter TEXT);
COMMIT;
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE albums (
      id TEXT PRIMARY KEY,
      artist_id TEXT NOT NULL,
      name TEXT NOT NULL,
      created_at INTEGER NOT NULL
    , image_file TEXT, image_prompt TEXT);
COMMIT;
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE voices (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      file TEXT NOT NULL,
      duration_sec REAL,
      created_at INTEGER NOT NULL
    , artist_id TEXT, f0_median_hz REAL, sing_low_hz REAL, sing_high_hz REAL, register TEXT, profile TEXT, clean_file TEXT, use_clean INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'speech', source_song_id TEXT, sculpt_file TEXT, sculpt_params TEXT, use_sculpt INTEGER NOT NULL DEFAULT 0);
COMMIT;
